  // \u2705 Use GCM mode (authenticated encryption)\n    const cipher = crypto.createCipheriv('aes-256-gcm', this.key, iv);\n\n    let encrypted = cipher.update(text, 'utf8', 'hex');\n    encrypted += cipher.final('hex');\n\n    // \u2705 Get authentication tag\n    const authTag = cipher.getAuthTag();\n\n    // \u2705 Return IV + authTag + ciphertext\n    return iv.toString('hex') + ':' + authTag.toString('hex') + ':' + encrypted;\n  }\n\n  decrypt(encryptedData: string): string {\n    try {\n      // \u2705 Extract IV, auth tag, and ciphertext\n      const parts = encryptedData.split(':');\n      if (parts.length !== 3) {\n        throw new Error('Invalid encrypted data format');\n      }\n\n      const iv = Buffer.from(parts[0], 'hex');\n      const authTag = Buffer.from(parts[1], 'hex');\n      const encrypted = parts[2];\n\n      // \u2705 Create decipher with IV\n      const decipher = crypto.createDecipheriv('aes-256-gcm', this.key, iv);\n\n      // \u2705 Set authentication tag\n      decipher.setAuthTag(authTag);\n\n      let decrypted = decipher.update(encrypted, 'hex', 'utf8');\n      decrypted += decipher.final('utf8');\n\n      return decrypted;\n    } catch (error) {\n      throw new Error('Decryption failed - data may be corrupted or tampered');\n    }\n  }\n}\n\n// payment.service.ts - SECURE\n@Injectable()\nexport class PaymentService {\n  constructor(\n    private encryption: EncryptionService,\n    private logger: Logger,\n  ) {}\n\n  // \u2705 SECURE: Proper encryption with PCI DSS compliance considerations\n  async saveCreditCard(userId: number, cardNumber: string) {\n    // \u2705 Validate card number format\n    if (!this.isValidCardNumber(cardNumber)) {\n      throw new BadRequestException('Invalid card number');\n    }\n\n    // \u2705 Encrypt using strong encryption\n    const encrypted = this.encryption.encrypt(cardNumber);\n\n    // \u2705 Store only last 4 digits in plain text (for display)\n    const last4 = cardNumber.slice(-4);\n\n   